import TreeUtils from "../components/CbaTree/TreeUtils";
import Utils from "../utils/Utils";
import IndexPathHelper from "./IndexPathHelper";
import RenderingHelper from "../components/RenderingHelper";
import CommonConfigHelper from "../config/CommonConfigHelper";
import StateAttributeAccess from './StateAttributeAccess';
import ComponentStateHelper from './ComponentStateHelper';

export default class TranslationTreeHelper {

    static translateTree = (treeIndexPath, runtime) => {
      if (this.shouldTranslateTree(treeIndexPath, runtime)) {
        const treeTranslationData = runtime.translationManager.getTranslationData(treeIndexPath, runtime);
        runtime.translationManager.translateGenericComponent(treeIndexPath, treeTranslationData, runtime);
        // update language in state: the tree language is used for shouldUpdate checks
        const translationLanguage = runtime.translationManager.getTranslationLanguage();
        ComponentStateHelper.updateStateAttribute(StateAttributeAccess.extractLanguageValue, StateAttributeAccess.setLanguageValue, translationLanguage, treeIndexPath, runtime, false);

        const { treeNodes, treeColumns, nodeTypes } = TreeUtils.getTreeDataByPath(treeIndexPath, runtime);
        const translatedTreeComponents = TranslationTreeHelper.translateTreeComponents(nodeTypes, treeNodes, treeColumns, runtime);
        const { translatedNodeTypes, translatedTreeNodes, translatedTreeColumns } = translatedTreeComponents;

        TreeUtils.setTreeDataByPath(treeIndexPath, runtime, translatedTreeNodes, null, translatedTreeColumns, translatedNodeTypes);

        // render component if visible
        const receiverComponent = runtime.componentDirectory.findComponent(treeIndexPath);
        const renderComponent = (receiverComponent !== undefined);
        if (renderComponent) {
          RenderingHelper.triggerRenderingViaPath(treeIndexPath, runtime);
        }
      }
    }

    static translateTreeComponents(nodeTypes, treeNodes, treeColumns, runtime) {
      const translatedNodeTypes = TranslationTreeHelper.translateTreeNodeTypes(nodeTypes, runtime);
      const translatedTreeNodes = TranslationTreeHelper.translateTreeNodes(treeNodes, runtime);
      const translatedTreeColumns = TranslationTreeHelper.translateTreeColumns(treeColumns, runtime);
      return {
        translatedNodeTypes,
        translatedTreeNodes,
        translatedTreeColumns
      };
    }

    // HelperMap: for the structures where nodeType userDefinedId is not present 
    // key: nodeType text 
    // value: nodeType text translation 
    static buildNodeTypeNameTranslationMap(nodeTypes, runtime) {
      const nodeTypeNameTranslationMap = new Map();
      nodeTypes.forEach((nodeType) => {
        const translatedText = runtime.translationManager.getTranslatedTextWithFallback(nodeType.userDefinedId, nodeType.name);
        nodeTypeNameTranslationMap.set(nodeType.name, translatedText);
      });
      return nodeTypeNameTranslationMap;
    }

    static translateTreeColumns(treeColumns, runtime) {
      treeColumns = Utils.deepCopy(treeColumns);
      treeColumns.map((column, index) => {
        const translationData = runtime.translationManager.getTranslationDataByUdi(column.userDefinedId, runtime);
        column.label = translationData.hasTextTranslation ? translationData.text : column.label;
        column.mouseOver = translationData.hasMouseOverTranslation ? translationData.mouseOver : column.mouseOver;
        return column;
      })
      return treeColumns;
    }

    static translateTreeNodes(treeNodes, runtime) {
      treeNodes = Utils.deepCopy(treeNodes);
      TreeUtils.parseNodes(treeNodes, (node) => {
        node.nodeType = runtime.translationManager.getTranslatedTextWithFallback(node.nodeTypeUserDefinedId, node.nodeType);
        // compute mouse over from translation data availability (node mouse over inherited from the node type if not present)
        const translationData = runtime.translationManager.getTranslationDataByUdi(node.userDefinedId, runtime);
        const nodeTypeTranslationData = runtime.translationManager.getTranslationDataByUdi(node.nodeTypeUserDefinedId, runtime);
        const nodeTypeTooltip = nodeTypeTranslationData.hasMouseOverTranslation ? nodeTypeTranslationData.mouseOver : node.tooltip;
        const nodeTypeImage = nodeTypeTranslationData.hasImageTranslation ? nodeTypeTranslationData.image : node.imagePath;
        node.tooltip = translationData.hasMouseOverTranslation ? translationData.mouseOver : nodeTypeTooltip;
        node.imagePath = CommonConfigHelper.getProperResourcePath(nodeTypeImage, runtime);

        let cellIndex = 0;
        node.cells = node.cells.map((cell, index) => {
          const translatedText = runtime.translationManager.getTranslatedTextWithFallback(`${node.userDefinedId}_${cellIndex}`, cell.label);
          const firstCellLabel = (translationData.hasTextTranslation ? translationData.text : cell.label);
          cell.label = (cellIndex === 0) ? firstCellLabel : translatedText;
          cell.mouseOver = node.tooltip;
          cellIndex += 1;
          return cell;
        });
        return true;
      })
      return treeNodes;
    }

    static translateTreeNodeTypes(nodeTypes, runtime) {
      nodeTypes = Utils.deepCopy(nodeTypes);
      const nodeTypeNameTranslationMap = TranslationTreeHelper.buildNodeTypeNameTranslationMap(nodeTypes, runtime);

      return nodeTypes.map((nodeType, index) => {
        // translate node type text, label
        const translationData = runtime.translationManager.getTranslationDataByUdi(nodeType.userDefinedId, runtime);
        nodeType.name = translationData.hasTextTranslation ? translationData.text : nodeType.name;
        nodeType.tooltip = translationData.hasMouseOverTranslation ? translationData.mouseOver : nodeType.tooltip;
        nodeType.image = translationData.hasImageTranslation ? translationData.image : nodeType.image;

        // translate node type child types
        nodeType.childTypes = (nodeType.childTypes || []).map(value => nodeTypeNameTranslationMap.get(value));

        // translate node type cellInitSettings
        let cellIndex = 0;
        nodeType.cellInitSettings = (nodeType.cellInitSettings || []).map((cellInitSetting) => {
          const translatedText = runtime.translationManager.getTranslatedTextWithFallback(`${nodeType.userDefinedId}_${cellIndex}`, cellInitSetting.label);
          cellInitSetting.label = (cellIndex === 0) ? nodeType.name : translatedText;
          cellInitSetting.mouseOver = nodeType.tooltip;
          cellIndex += 1;
          return cellInitSetting;
        })

        // translate node type contextMenuCommands
        nodeType.contextMenuCommands = (nodeType.contextMenuCommands || []).map((contextMenuCommand) => {
          (contextMenuCommand.submenu || []).map((submenu) => {
            const submenuTranslationData = runtime.translationManager.getTranslationDataByUdi(submenu.userDefinedId, runtime);
            submenu.label = submenuTranslationData.hasTextTranslation ? submenuTranslationData.text : submenu.label;
            return submenu;
          })
          return contextMenuCommand;
        })

        return nodeType;
      });
    }

    static shouldTranslateTree = (treeIndexPath, runtime) => {
      const { config } = runtime.pageConfigurationsManager.findConfigurationForPageSegment(IndexPathHelper.getLastPageSegmentFromPath(treeIndexPath));
      const { nodes } = config;
      const { treeNodes } = TreeUtils.getTreeDataByPath(treeIndexPath, runtime);

      return TranslationTreeHelper.shouldTranslateNodes(TranslationTreeHelper.flattenTreeNodes(nodes), TranslationTreeHelper.flattenTreeNodes(treeNodes), treeIndexPath, runtime);
    }

    static shouldTranslateNodes = (configNodes, stateNodes, treeIndexPath, runtime) => {
      // if new node is present in state, do not translate
      if (configNodes.length !== stateNodes.length) return false;
      return configNodes.every((configNode) => {
        const { userDefinedId } = configNode;
        const stateNode = stateNodes.find(node => node.userDefinedId === userDefinedId);

        // if a node is not present in state anymore, do not translate
        if (stateNode === undefined) return false;

        // if a node was renamed, do not translate
        if (stateNode.cells === undefined || stateNode.cells.length === 0) return false;
        const stateNodeTypeName = stateNode.cells[0].label;
        const componentLanguage = runtime.translationManager.retrieveComponentLanguage(treeIndexPath, runtime);
        const translatedNodeName = runtime.translationManager.getTranslatedText4GivenLanguage(userDefinedId, componentLanguage);
        if (stateNodeTypeName !== translatedNodeName) return false;

        return true;
      });
    }

    static flattenTreeNodes = (treeNodes) => {
      const result = [];

      const traverse = (node) => {
        result.push(node);
        if (node.nodes) {
          node.nodes.forEach(traverse);
        }
      };

      treeNodes.forEach(traverse);
      return result;
    };

}
