import StateAttributeAccess from './StateAttributeAccess';
import ComponentStateHelper from './ComponentStateHelper';
import PathTranslationHelper from './PathTranslationHelper';
import UserDefPathHelper from './UserDefPathHelper';
import IndexPathHelper from "./IndexPathHelper";
import TableHelper from "../components/table/TableHelper";
import SelectGroupHelper from "../components/SelectGroupHelper";

export default class TranslationTableHelper {

    static updateTableCellEditor = (tableCellEditorPath, runtime) => {
      // translate mouseovers (address, content)
      const receiverComponent = runtime.componentDirectory.findComponent(tableCellEditorPath);
      const renderComponent = (receiverComponent !== undefined);
      const absoluteUserDefPath = PathTranslationHelper.getUserDefPathForIndexPath(tableCellEditorPath, runtime);
      const userDefinedId = UserDefPathHelper.getLastUserDefIdFromPath(absoluteUserDefPath);

      const mouseOverCellEditorAddressKey = `${userDefinedId}_MouseOverTextCellAddress`;
      const translatedMouseOverCellEditorAddressValue = runtime.translationManager.getTranslatedMouseOver(mouseOverCellEditorAddressKey);
      if (translatedMouseOverCellEditorAddressValue !== null) {
        ComponentStateHelper.updateStateAttribute(StateAttributeAccess.extractMouseOverCellEditorAddress, StateAttributeAccess.setMouseOverCellEditorAddress, translatedMouseOverCellEditorAddressValue, tableCellEditorPath, runtime, renderComponent);
      }
      const mouseOverCellEditorContentKey = `${userDefinedId}_MouseOverTextCellContent`;
      const translatedMouseOverCellEditorContentValue = runtime.translationManager.getTranslatedMouseOver(mouseOverCellEditorContentKey);
      if (translatedMouseOverCellEditorContentValue !== null) {
        ComponentStateHelper.updateStateAttribute(StateAttributeAccess.extractMouseOverCellEditorContent, StateAttributeAccess.setMouseOverCellEditorContent, translatedMouseOverCellEditorContentValue, tableCellEditorPath, runtime, renderComponent);
      }

      // update content when the component is not visible when table changes
      if (!renderComponent) {
        const { config } = runtime.pageConfigurationsManager.findConfigurationForPageSegment(IndexPathHelper.getLastPageSegmentFromPath(tableCellEditorPath));
        const cellEditorPathWithoutLastPageSegment = IndexPathHelper.dropPageSegmentFromPath(tableCellEditorPath);
        const attachedTablePath = IndexPathHelper.appendPageSegmentsToPath(cellEditorPathWithoutLastPageSegment, config.attachedTable);
        const selectedCell = ComponentStateHelper.getStateAttributeByPathId(StateAttributeAccess.extractSelectedCell, attachedTablePath, runtime);
        const tableData = ComponentStateHelper.getStateAttributeByPathId(StateAttributeAccess.extractTableData, attachedTablePath, runtime);
        if (selectedCell !== undefined) {
          const updatedContentValue = tableData[selectedCell.row][selectedCell.column];
          ComponentStateHelper.updateStateAttribute(StateAttributeAccess.extractCellEditorContent, StateAttributeAccess.setCellEditorContent, updatedContentValue, tableCellEditorPath, runtime, false);
        }
      }
    }

    static translateTable = (tablePath, runtime) => {
      if (TranslationTableHelper.shouldUpdateTableTexts(tablePath, runtime)) {
        const tableTranslationData = runtime.translationManager.getTranslationData(tablePath, runtime);
        runtime.translationManager.translateGenericComponent(tablePath, tableTranslationData, runtime);

        const tableAbsoluteUserDefPath = PathTranslationHelper.getUserDefPathForIndexPath(tablePath, runtime);
        const tableData = ComponentStateHelper.getStateAttributeByUserDefPath(StateAttributeAccess.extractTableData, tableAbsoluteUserDefPath, runtime);
        const receiverComponent = runtime.componentDirectory.findComponent(tablePath);
        const renderedComponent = (receiverComponent !== undefined);
        let filteredTableCells = TranslationTableHelper.findRelevantTableCells(tablePath, runtime);
        // process first cell at the end, so that the focus is set to this one
        if (filteredTableCells.length > 0) {
          filteredTableCells = filteredTableCells.slice(1).concat(filteredTableCells[0]);
        }

        filteredTableCells.forEach((memberPath) => {
          // translate cell
          const cellTranslationData = runtime.translationManager.getTranslationData(memberPath, runtime);
          //  update table cell text for combos (tableCellUDI_selectedIndex as translation key)
          const { config } = runtime.pageConfigurationsManager.findConfigurationForPageSegment(IndexPathHelper.getLastPageSegmentFromPath(memberPath));
          const { row, column, readOnly, items } = config;
          if (items !== undefined) {
            items.forEach((itemConfig, index, all) => {
              const itemPath = IndexPathHelper.appendIndexToPageSegment(IndexPathHelper.appendIndexToPageSegment(memberPath, 0), index);
              const itemState = runtime.componentStateManager.findOrBuildStateForPathId(itemPath, runtime);
              if (SelectGroupHelper.extractSelectedState(itemState, itemPath, runtime)) {
                let translationUdi = UserDefPathHelper.getLastUserDefIdFromPath(PathTranslationHelper.getUserDefPathForIndexPath(memberPath, runtime));
                translationUdi += `_${index}`;
                const translation = runtime.translationManager.getTranslatedText(translationUdi);
                cellTranslationData.text = translation;
                cellTranslationData.hasTextTranslation = (translation !== undefined);
              }
            });
          }
          runtime.translationManager.translateGenericComponent(memberPath, cellTranslationData, runtime);

          // update table
          const updatedValue = (cellTranslationData.text === null) ? '' : cellTranslationData.text;
          if (tableData !== undefined) {
            tableData[row][column] = updatedValue;
          }
          if (renderedComponent) {
            runtime.eventEmitter.emit(`${tablePath}-contentUpdate`, updatedValue, row, column, readOnly);
          }

          // update edit widgets
          const editMemberPath = IndexPathHelper.appendIndexToPageSegment(memberPath, 0);
          const editComponentType = ComponentStateHelper.getComponentTypeForIndexPath(editMemberPath, runtime);
          if (editComponentType === 'CbaSingleLineInputField') {
            const formula = ComponentStateHelper.getStateAttributeByPathId(StateAttributeAccess.extractFormula, memberPath, runtime);
            const updateEditWidgetValue = (formula !== undefined && TableHelper.isFormula(formula)) ? formula : cellTranslationData.text;
            cellTranslationData.text = updateEditWidgetValue;
            cellTranslationData.hasTextTranslation = (updateEditWidgetValue !== undefined);
            runtime.translationManager.translateGenericComponent(editMemberPath, cellTranslationData, runtime);
          } else if (editComponentType === 'CbaComboBox') {
            const memberPaths = ComponentStateHelper.findIndexPathsOfDescendants(editMemberPath, runtime);
            memberPaths.forEach((comboItemPath) => {
              let translationUdi = UserDefPathHelper.getLastUserDefIdFromPath(PathTranslationHelper.getUserDefPathForIndexPath(memberPath, runtime));
              translationUdi += `_${UserDefPathHelper.getLastUserDefIdFromPath(PathTranslationHelper.getUserDefPathForIndexPath(comboItemPath, runtime))}`;
              const translation = runtime.translationManager.getTranslatedText(translationUdi);
              cellTranslationData.text = translation;
              cellTranslationData.hasTextTranslation = (translation !== undefined);
              runtime.translationManager.translateGenericComponent(comboItemPath, cellTranslationData, runtime);
            });
          }
        })

        if (tableData !== undefined) {
          ComponentStateHelper.updateStateAttribute(StateAttributeAccess.extractTableData, StateAttributeAccess.setTableData, tableData, tablePath, runtime, false);
        }
      }
    }

    static shouldUpdateTableTexts = (memberPath, runtime) => {
      const { config } = runtime.pageConfigurationsManager.findConfigurationForPageSegment(IndexPathHelper.getLastPageSegmentFromPath(memberPath));
      if (!config.isSpreadsheet) return false;

      const filteredCells = TranslationTableHelper.findRelevantTableCells(memberPath, runtime);
      const shouldUpdate = filteredCells.every((cellPath) => {
        const absoluteUserDefId = PathTranslationHelper.getUserDefPathForIndexPath(cellPath, runtime);

        // should update regardless of combos values
        const editMemberPath = IndexPathHelper.appendIndexToPageSegment(cellPath, 0);
        const editComponentType = ComponentStateHelper.getComponentTypeForIndexPath(editMemberPath, runtime);
        if (editComponentType === 'CbaComboBox') return true;

        const componentLanguage = runtime.translationManager.retrieveComponentLanguage(cellPath, runtime);
        const userDefId = UserDefPathHelper.getLastUserDefIdFromPath(absoluteUserDefId);
        let textFromState = ComponentStateHelper.getStateAttributeByPathId(StateAttributeAccess.extractTextValue, cellPath, runtime);
        const formula = ComponentStateHelper.getStateAttributeByPathId(StateAttributeAccess.extractFormula, cellPath, runtime);
        if (formula !== undefined && TableHelper.isFormula(formula)) textFromState = formula;
        if (textFromState === undefined) return true;
        const referenceTextTranslation = runtime.translationManager.getTranslatedText4GivenLanguage(userDefId, componentLanguage);
        return (textFromState === referenceTextTranslation);
      });
      return shouldUpdate;
    }

    static findRelevantTableCells = (tablePath, runtime) => {
      const memberPaths = ComponentStateHelper.findIndexPathsOfDescendants(tablePath, runtime);
      return memberPaths.filter((tableMemberPath) => {
        const componentType = ComponentStateHelper.getComponentTypeForIndexPath(tableMemberPath, runtime);
        if (componentType === 'CbaTableCell') {
          const cellConfig = runtime.pageConfigurationsManager.findConfigurationForPageSegment(IndexPathHelper.getLastPageSegmentFromPath(tableMemberPath)).config;
          const { row, column } = cellConfig;
          if (row > 0 && column > 0) return true;
        }
        return false;
      });
    }

}
