import StateAttributeAccess from "./StateAttributeAccess";
import CbaRichTextField from "../components/CbaRichTextField/CbaRichTextField";
import ComponentStateHelper from "./ComponentStateHelper";
import PathTranslationHelper from "./PathTranslationHelper";
import UserDefPathHelper from "./UserDefPathHelper";
import IndexPathHelper from "./IndexPathHelper";
import Utils from "../utils/Utils";

export default class TranslationRichTextFieldHelper {

  static getRichTextTranslation(userDefId, runtime, language) {
    const { translationManager } = runtime;
    const translationObjectAsString = (language !== undefined) ? translationManager.getTranslatedObject4GivenLanguage(userDefId, language) : translationManager.getTranslatedObject(userDefId);
    if (translationObjectAsString !== null) {
      try {
        return JSON.parse(translationObjectAsString);
      } catch (error) {
        return null;
      }
    }
    return null;
  }

  /**
   * Build the initial state for translation in the component state manager. 
   */
  static addAttributesToInitialState(indexPath, initialState, runtime) {
    const userDefIdPath = PathTranslationHelper.getUserDefPathForIndexPath(indexPath, runtime);
    const userDefId = UserDefPathHelper.getLastUserDefIdFromPath(userDefIdPath);
    const translation = this.getRichTextTranslation(userDefId, runtime);
    if (translation === null) return;

    const translationLanguage = runtime.translationManager.getTranslationLanguage();
    TranslationRichTextFieldHelper.mapTranslationOnConfig(indexPath, translationLanguage, translation, runtime);
    StateAttributeAccess.setLanguageValue(initialState, translationLanguage);

    const { config } = runtime.pageConfigurationsManager.findConfigurationForPageSegment(IndexPathHelper.getLastPageSegmentFromPath(indexPath));
    initialState.editorState = CbaRichTextField.buildInitialEditorState(config);
    StateAttributeAccess.setTextValue(initialState, CbaRichTextField.calculateTextValue(initialState.editorState));
  }

  static translateRichTextField(indexPath, runtime) {
    const { translationManager } = runtime;

    // generic translation e.g. mouseover
    const translationData = translationManager.getTranslationData(indexPath, runtime);
    translationManager.translateGenericComponent(indexPath, translationData, runtime);

    // component translation 
    const absoluteUserDefPath = PathTranslationHelper.getUserDefPathForIndexPath(indexPath, runtime);
    const userDefinedId = UserDefPathHelper.getLastUserDefIdFromPath(absoluteUserDefPath);
    const translation = this.getRichTextTranslation(userDefinedId, runtime);
    if (translation === null) return;

    const receiverComponent = runtime.componentDirectory.findComponent(indexPath);
    const renderedComponent = (receiverComponent !== undefined);

    const translationLanguage = translationManager.getTranslationLanguage();
    TranslationRichTextFieldHelper.mapTranslationOnConfig(indexPath, translationLanguage, translation, runtime);
    ComponentStateHelper.updateStateAttribute(StateAttributeAccess.extractLanguageValue, StateAttributeAccess.setLanguageValue, translationLanguage, indexPath, runtime, false);

    // reset existing selections and modifiers
    ComponentStateHelper.updateStateAttribute(StateAttributeAccess.extractSelections, StateAttributeAccess.setSelections, [], indexPath, runtime, false);
    ComponentStateHelper.updateStateAttribute(StateAttributeAccess.extractModifiersInEditorState, StateAttributeAccess.setModifiersInEditorState, {}, indexPath, runtime, false);

    const { config } = runtime.pageConfigurationsManager.findConfigurationForPageSegment(IndexPathHelper.getLastPageSegmentFromPath(indexPath));
    const initialEditorState = CbaRichTextField.buildInitialEditorState(config);
    ComponentStateHelper.updateStateAttribute(StateAttributeAccess.extractEditorState, StateAttributeAccess.setEditorState, initialEditorState, indexPath, runtime, renderedComponent);

    const textValue = CbaRichTextField.calculateTextValue(initialEditorState);
    ComponentStateHelper.updateStateAttribute(StateAttributeAccess.extractTextValue, StateAttributeAccess.setTextValue, textValue, indexPath, runtime, renderedComponent);
  }

  static mapTranslationOnConfig(indexPath, translationLanguage, translation, runtime) {
    const { config } = runtime.pageConfigurationsManager.findConfigurationForPageSegment(IndexPathHelper.getLastPageSegmentFromPath(indexPath));
    const oldConfig = Utils.safeDeepCopy(config);

    TranslationRichTextFieldHelper.mapTranslationOnGivenConfig(config, translationLanguage, translation);

    runtime.pageConfigurationsManager.updateMappingsForRichTextField(IndexPathHelper.getLastPageSegmentFromPath(indexPath), oldConfig, config);
  }

  static mapTranslationOnGivenConfig(config, translationLanguage, translation) {
    const { value, stylesMap, textBlocks, contentModifiers } = translation;
    config.language = translationLanguage;
    config.value = value;
    config.stylesMap = stylesMap;
    if (textBlocks !== undefined) config.textBlocks = textBlocks;
    if (contentModifiers !== undefined) config.contentModifiers = contentModifiers;
  }


}
