import ComponentStateHelper from "./ComponentStateHelper";
import PathTranslationHelper from "./PathTranslationHelper";
import UserDefPathHelper from "./UserDefPathHelper";
import IndexPathHelper from "./IndexPathHelper";
import StateAttributeAccess from "./StateAttributeAccess";
import TranslationRichTextFieldHelper from "./TranslationRichTextFieldHelper";

export default class TranslationInitStateHelper {

  static addTranslationsInState(pathId, config, result, runtime) {
    const { translationLanguage } = runtime.translationManager;
    if (translationLanguage === '') return;

    const componentType = ComponentStateHelper.getComponentTypeForIndexPath(pathId, runtime);
    const userDefIdPath = PathTranslationHelper.getUserDefPathForIndexPath(pathId, runtime);
    let userDefId = UserDefPathHelper.getLastUserDefIdFromPath(userDefIdPath);

    const adaptedUdi = TranslationInitStateHelper.recomputeUdiForDynamicTableCell(pathId, runtime);
    if (adaptedUdi !== undefined) userDefId = adaptedUdi;
    TranslationInitStateHelper.setTranslatedText(userDefId, result, runtime);
    TranslationInitStateHelper.setTranslatedMouseOver(userDefId, result, runtime);

    const adaptedUdi4Image = TranslationInitStateHelper.recomputeUdiForImageMaps(pathId, config, runtime);
    if (adaptedUdi4Image !== undefined) userDefId = adaptedUdi4Image;
    TranslationInitStateHelper.setTranslatedImage(userDefId, result, runtime);

    if (componentType === 'CbaTableCell') {
      const translatedCellText = runtime.translationManager.getTranslatedText(userDefId);
      TranslationInitStateHelper.updateTableCellParentState(pathId, config, translatedCellText, runtime);
    }

    // specific attributes
    if (componentType === 'CbaTableCellEditor') {
      TranslationInitStateHelper.setTableCellEditorMouseOvers(userDefId, result, runtime);
    }

    if (componentType === 'CbaRichTextField') {
      TranslationRichTextFieldHelper.addAttributesToInitialState(pathId, result, runtime);
    }
  }

  // imageMap -> compute userDefinedId for the image (generated in parent container)
  static recomputeUdiForImageMaps(pathId, config, runtime) {
    const componentType = ComponentStateHelper.getComponentTypeForIndexPath(pathId, runtime);
    if (componentType === 'CbaContainer') {
      const { imageMapUserDefinedId } = config;
      return imageMapUserDefinedId;
    }
    return undefined;
  }

  static recomputeUdiForDynamicTableCell(pathId, runtime) {
    const componentType = ComponentStateHelper.getComponentTypeForIndexPath(pathId, runtime);
    const userDefIdPath = PathTranslationHelper.getUserDefPathForIndexPath(pathId, runtime);
    const userDefId = UserDefPathHelper.getLastUserDefIdFromPath(userDefIdPath);

    // single line input fields (table cells), use table cell as reference
    if (componentType === 'CbaSingleLineInputField' && userDefId === undefined) {
      const cellPathId = IndexPathHelper.dropIndexFromPageSegment(pathId);
      const cellUserDefIdPath = PathTranslationHelper.getUserDefPathForIndexPath(cellPathId, runtime);
      return UserDefPathHelper.getLastUserDefIdFromPath(cellUserDefIdPath);
    }

    // combo items (table cells) -> compute userDefinedId keys from translation (cellUdi_comboItemUdi)
    if (componentType === 'ComboBoxItem' && /^\d/.test(userDefId)) {
      const comboPathId = IndexPathHelper.dropIndexFromPageSegment(pathId);
      const cellPathId = IndexPathHelper.dropIndexFromPageSegment(comboPathId);
      const cellUserDefIdPath = PathTranslationHelper.getUserDefPathForIndexPath(cellPathId, runtime);
      const cellUserDefId = UserDefPathHelper.getLastUserDefIdFromPath(cellUserDefIdPath);
      return `${cellUserDefId}_${userDefId}`;
    }
    return undefined;
  }

  static updateTableCellParentState(pathId, config, translatedText, runtime) {
    if (translatedText !== null) {
      const tableIndexPath = IndexPathHelper.dropIndexFromPageSegment(pathId);
      const tableAbsoluteUserDefPath = PathTranslationHelper.getUserDefPathForIndexPath(tableIndexPath, runtime);
      const tableData = ComponentStateHelper.getStateAttributeByUserDefPath(StateAttributeAccess.extractTableData, tableAbsoluteUserDefPath, runtime);
      if (tableData !== undefined) {
        tableData[config.row][config.column] = translatedText;
        ComponentStateHelper.updateStateAttribute(StateAttributeAccess.extractTableData, StateAttributeAccess.setTableData, tableData, tableIndexPath, runtime, false);
      }
    }
  }

  // --- TEXT translation ---
  static setTranslatedText(userDefId, result, runtime) {
    const { currentLanguage } = runtime.translationManager;
    const translatedText = runtime.translationManager.getTranslatedText(userDefId);
    if (translatedText !== null) {
      StateAttributeAccess.setTextValue(result, translatedText);
      StateAttributeAccess.setLanguageValue(result, currentLanguage);
    }
  }

  // --- MouseOver translation ---
  static setTranslatedMouseOver(userDefId, result, runtime) {
    const translatedMouseOver = runtime.translationManager.getTranslatedMouseOver(userDefId);
    if (translatedMouseOver !== null) {
      StateAttributeAccess.setMouseOverValue(result, translatedMouseOver);
    }
  }

  // --- IMAGE translation ---
  static setTranslatedImage(userDefId, result, runtime) {
    const translatedImage = runtime.translationManager.getTranslatedImage(userDefId);
    if (translatedImage !== null) {
      StateAttributeAccess.setDefaultImage(result, translatedImage);
    }
  }

  // mouse over TableCellEditor address/content (udi_MouseOverTextCellAddress/Content)
  static setTableCellEditorMouseOvers(userDefId, result, runtime) {
    const mouseOverCellEditorAddressKey = `${userDefId}_MouseOverTextCellAddress`;
    const translatedMouseOverCellEditorAddressValue = runtime.translationManager.getTranslatedMouseOver(mouseOverCellEditorAddressKey);
    if (translatedMouseOverCellEditorAddressValue !== null) {
      StateAttributeAccess.setMouseOverCellEditorAddress(result, translatedMouseOverCellEditorAddressValue);
    }
    const mouseOverCellEditorContentKey = `${userDefId}_MouseOverTextCellContent`;
    const translatedMouseOverCellEditorContentValue = runtime.translationManager.getTranslatedMouseOver(mouseOverCellEditorContentKey);
    if (translatedMouseOverCellEditorContentValue !== null) {
      StateAttributeAccess.setMouseOverCellEditorContent(result, translatedMouseOverCellEditorContentValue);
    }
  }

}
